-- =============================================================================
-- Datos de demostración "en funcionamiento" (equivalente a DemoFuncionamientoSeeder)
-- Generado el 2026-10-22 a partir de los datos demo locales.
--
-- Pegar completo en Supabase → SQL Editor → Run. Es idempotente: si se corre
-- dos veces no duplica nada. Para quitarlo: demo_funcionamiento_limpiar.sql
-- Ciudadanos demo: usuario = CURP en minúsculas, contraseña Demo2026
-- =============================================================================

BEGIN;

-- Columnas de ciudadano (migración 2026-09-02-000015), por si faltan.
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS curp VARCHAR(18) NULL;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS apellido VARCHAR(120) NULL;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS estado VARCHAR(100) NULL;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS ciudad VARCHAR(150) NULL;

-- Ciudadanos
  SELECT u.id, r.id, NOW(), NOW() FROM public.users u CROSS JOIN public.roles r
  WHERE r.nombre = 'ciudadano' AND u.curp IN ('RAGL880214MGTMRR03', 'MOSJ790611HGTRNN08', 'TOVA920830MGTRLN05', 'GUPE850107HGTTRD01', 'HEMM950322MGTRRR09', 'LOCR810915HGTPHB02', 'VEGS900428MGTLRF06', 'CAMD870703HGTSRV04', 'ROJP930119MGTDMT07', 'BASM760925HGTTTG03')
  AND NOT EXISTS (SELECT 1 FROM public.user_roles x WHERE x.user_id = u.id AND x.role_id = r.id);

-- Convocatoria

