-- Boletas de infracción (el nombre del agente se toma de agentes_transito si existe)

-- Resincroniza secuencias (por si quedaron atrás de los ids existentes).
SELECT setval(pg_get_serial_sequence('public.users', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM public.users), 1));
SELECT setval(pg_get_serial_sequence('public.user_roles', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM public.user_roles), 1));
SELECT setval(pg_get_serial_sequence('public.convocatorias', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM public.convocatorias), 1));
SELECT setval(pg_get_serial_sequence('public.solicitudes', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM public.solicitudes), 1));
SELECT setval(pg_get_serial_sequence('public.solicitud_datos', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM public.solicitud_datos), 1));
SELECT setval(pg_get_serial_sequence('public.historial_estatus', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM public.historial_estatus), 1));
SELECT setval(pg_get_serial_sequence('public.verificaciones_fisicas', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM public.verificaciones_fisicas), 1));
SELECT setval(pg_get_serial_sequence('public.boletas_infracciones', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM public.boletas_infracciones), 1));

COMMIT;

-- Comprobación rápida
